"""Build a local searchable gallery from collected source records."""
from pathlib import Path
import json,html
p=Path('素材库');d=json.loads((p/'index.json').read_text(encoding='utf-8'))
cards=[]
for r in d['records']:
    h=html.escape
    category=r.get('category','待确认')
    tags=category+' '+r['query']+' '+r['mediaType']+' '+r['visibleText']
    link=r.get('detailUrl') or r['source']
    cards.append('<article data-category="'+h(category,quote=True)+'" data-type="'+h(r['mediaType'],quote=True)+'" data-pending="'+str(bool(r.get('previewNeedsReview'))).lower()+'" data-search="'+h(tags,quote=True)+'"><img loading="lazy" src="'+h(r['screenshot'].replace('\\','/'),quote=True)+'"><div><b>'+h(category+' · '+r['mediaType'])+'</b><p>'+h(r['visibleText'][:300])+'</p><small>'+h(r.get('classificationStatus','分类待确认')+'；原检索词：'+r['query']+'；'+r.get('visualReview','预览待核'))+'</small><p><a href="'+h(link,quote=True)+'" target="_blank" rel="noopener">查看来源</a></p></div></article>')
doc='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>广告对标素材库</title><style>body{margin:0;background:#f4f6f9;color:#18232e;font:16px/1.6 system-ui}header{padding:28px 4vw;background:white;position:sticky;top:0;z-index:2;box-shadow:0 2px 10px #ddd}h1{margin:0}input,select{padding:10px;border:1px solid #ccc;border-radius:8px;margin:8px 6px 0 0;font:inherit}main{padding:24px 4vw;display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:18px}article{background:white;border-radius:12px;overflow:hidden;border:1px solid #ddd}article img{width:100%;height:260px;object-fit:contain;background:#e9edf3}article div{padding:16px}p{white-space:pre-wrap;margin:8px 0}small{color:#52606e}a{color:#165dcc}</style><header><h1>广告对标素材库</h1><p>按平台详情行业或画面初筛分类。初筛不是官方确认；得分不保证效果。图片为来源卡片截图，未下载原始媒体。</p><input id="q" placeholder="搜索行业、品牌或文案"><select id="type"><option value="">全部类型</option><option>视频</option><option>图片</option></select><select id="category"><option value="">全部分类</option></select><label><input type="checkbox" id="pending">显示不完整预览</label><span id="count"></span><p><a href="公网案例/案例索引.md">公网案例候选目录</a></p></header><main>'''+''.join(cards)+'''</main><script>const category=document.querySelector('#category'),pending=document.querySelector('#pending');const q=document.querySelector('#q'),type=document.querySelector('#type'),cards=[...document.querySelectorAll('article')];for(const label of [...new Set(cards.map(c=>c.dataset.category))].sort()){const o=document.createElement('option');o.value=o.textContent=label;category.append(o)}function filter(){let n=0;for(const c of cards){const s=c.dataset.search;const yes=s.toLowerCase().includes(q.value.toLowerCase())&&(!type.value||c.dataset.type===type.value)&&(!category.value||c.dataset.category===category.value)&&(pending.checked||c.dataset.pending!=='true');c.hidden=!yes;if(yes)n++}document.querySelector('#count').textContent=n+' 条'}q.oninput=type.onchange=category.onchange=pending.onchange=filter;filter()</script></html>'''
(p/'浏览素材库.html').write_text(doc,encoding='utf-8')
print('Gallery records: '+str(len(cards)))
